using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using TMPro;
public static class IsolateChapterHudFont {
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene");const string original="Assets/ShooterSurvival/Resources/UI/GmarketHarbor SDF.asset";const string target="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedMall-20261003T092859667/Chapter45 runtime HUD font.asset";if(AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(target)!=null)throw new Exception("Already applied");if(!AssetDatabase.CopyAsset(original,target))throw new Exception("Copy failed");var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(target);var shared=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(original);var texts=new System.Text.StringBuilder();foreach(string p in Directory.GetFiles("Assets/ShooterSurvival/Scripts/Game/Chapters45","*.cs"))texts.Append(File.ReadAllText(p));texts.Append(File.ReadAllText("tools/apply-street-detail.cs"));texts.Append(File.ReadAllText("Assets/ShooterSurvival/Scripts/Game/RestStopHoldout.cs"));texts.Append("←→·0123456789최고의신발매장체력공격력보상얻음코인실패성공다시시작계속하기");string chars=new string(texts.ToString().Where(c=>c>='가'&&c<='힣'||c>=' '&&c<='~'||"←→·".Contains(c)).Distinct().ToArray());font.atlasPopulationMode=AtlasPopulationMode.Dynamic;string missing;font.TryAddCharacters(chars,out missing);font.atlasPopulationMode=AtlasPopulationMode.Static;AssetDatabase.SaveAssetIfDirty(font);var rows=new List<object>();var setup=EditorSceneManager.GetSceneManagerSetup();
  try{foreach(string name in new[]{"Jamsil","ShoeTower"}){var scene=EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/"+name+".unity");int count=0;foreach(var t in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TMP_Text>(true))){if(t.font!=shared)continue;t.font=font;t.fontSharedMaterial=font.material;count++;}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);rows.Add(new{scene=name,count});}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return new{font=target,staticAtlas=true,requestedCharacters=chars.Length,missing,scenes=rows.ToArray()};
 }
}
